head.script:
scwin.onpageload = function() {};
scwin.onpageunload = function() {};
scwin.ibx_openPopup_onclick = function(e) {
    var dataObj = {
        type: "json", // 데이터 타입. "xml","string","json","array" 
        data: {
            "t": "x"
        }, // 전달 데이터 객체. 
        name: "paramData" // 변수명. popup에서 $w.getParameter( "rowObj" )로 깨내올 수 있다. 
    };
    var opts = {
        "id": "popup1",
        "type": "browserPopup",
        "width": "700px",
        "height": "250px",
        "top": 250,
        "left": 250,
        "popupName": "Popup2",
        "modal": false,
        "dataObject": dataObj,
        "title": "browserPopup"
    };
    $p.openPopup("popup_browserPopup_getCurrentServerDate_WESD-180_(WSQ-4342)_sub.xml", opts);
};
scwin.ibx_closePopup_onclick = function(e) {
    $p.closePopup("popup1");
};
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    if(WebSquare._xv !== "SP5"){requires("uiplugin.popup");}
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}
